int healthPoints = 50;
boolean hasEnergyShield = true;

// Logical AND (&&): Requires BOTH parameters to evaluate as TRUE
if (healthPoints > 0 && hasEnergyShield == true) {
    System.out.println("Player is structurally safe.");
}

// Logical OR (||): Requires ONLY ONE parameter to evaluate as TRUE
if (healthPoints < 10 || hasEnergyShield == false) {
    System.out.println("System Status Alert: Vulnerable Core!");
}

// Logical NOT (!): Inverts the current boolean state flag
if (!hasEnergyShield) {
    System.out.println("Deploy shield matrix immediately!");
}

