// SCENARIO A: PREFIX MODE (++var / --var)
// Rule: Mutate the memory location FIRST, then evaluate the variable inside the statement.
int primaryCores = 10;
int targetCores = ++primaryCores; 
// Result: primaryCores becomes 11, targetCores receives 11.

// SCENARIO B: POSTFIX MODE (var++ / var--)
// Rule: Evaluate the old value inline FIRST, then mutate memory in the background.
int legacyThreads = 10;
int runtimeThreads = legacyThreads--; 
// Result: runtimeThreads receives original 10; legacyThreads drops to 9 in RAM.

